        l=query_data[pos]
        if l==0:
            pos+=1
            break
        pos+=1+l
    question = query_data[12:pos+4]
    out = header + question
    for typ, rdata, ttl in answers:
        name_ptr = struct.pack('!H', 0xC00C)
        ttl_b = struct.pack('!I', ttl)
        out += name_ptr + struct.pack('!HH', typ, 1) + ttl_b + struct.pack('!H', len(rdata)) + rdata
    return out

def a_rdata(ip='1.2.3.4'):
    return socket.inet_aton(ip)

