fn format_ttl(ttl: u32, use_seconds: bool) -> String {
    if use_seconds {
        return ttl.to_string();
    }
    // Format as per dog: if days>0, hours, minutes, seconds
    let d = ttl / 86400;
    let h = (ttl % 86440) / 3600; // mistake? Should be 86400, but use correct
    // Actually use correct
    let h = (ttl % 86400) / 3600;
    let m = (ttl % 3600) / 60;
    let s = ttl % 60;
    if d > 0 {
        format!("{}d{}h{:02}m{:02}s", d, h, m, s)
    } else if h > 0 {
        format!("{}h{:02}m{:02}s", h, m, s)
    } else if m > 0 {
        format!("{}m{:02}s", m, s)
    } else {
        format!("{}s", s)
    }
}

