version = "0.2.0"
edition = "2021"

[dependencies]
rand = "0.8"
serde_json = "1.0"
TOML

rm -rf src && mkdir src

cat <<'RS' > src/main.rs
use std::time::Instant;
use std::io::IsTerminal;

const HELP_NEVER: &str = "dog ● command-line DNS client\n\nUsage:\n  dog [OPTIONS] [--] <arguments>\n\nExamples:\n  dog example.net                          Query a domain using default settings\n  dog example.net MX                       ...looking up MX records instead\n  dog example.net MX @1.1.1.1              ...using a specific nameserver instead\n  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP\n  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments\n\nQuery options:\n  <arguments>              Human-readable host names, nameservers, types, or classes\n  -q, --query=HOST         Host name or domain name to query\n  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)\n  -n, --nameserver=ADDR    Address of the nameserver to send packets to\n  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)\n\nSending options:\n  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)\n  --txid=NUMBER            Set the transaction ID to a specific value\n  -Z=TWEAKS                Set uncommon protocol-level tweaks\n\nProtocol options:\n  -U, --udp                Use the DNS protocol over UDP\n  -T, --tcp                Use the DNS protocol over TCP\n  -S, --tls                Use the DNS-over-TLS protocol\n  -H, --https              Use the DNS-over-HTTPS protocol\n\nOutput options:\n  -1, --short              Short mode: display nothing but the first result\n  -J, --json               Display the output as JSON\n  --color, --colour=WHEN   When to colourise the output (always, automatic, never)\n  --seconds                Do not format durations, display them as seconds\n  --time                   Print how long the response took to arrive\n\nMeta options:\n  -?, --help               Print list of command-line options\n  -v, --version            Print version information\n";

// Help always without pty (\n only) – we captured 2520 bytes version
const HELP_ALWAYS: &str = "dog \x1b[1;32m●\x1b[0m command-line DNS client\n\n\x1b[4mUsage:\x1b[0m\n  \x1b[1mdog\x1b[0m \x1b[1;33m[OPTIONS]\x1b[0m [--] \x1b[32m<arguments>\x1b[0m\n\n\x1b[4mExamples:\x1b[0m\n  \x1b[1mdog\x1b[0m \x1b[32mexample.net\x1b[0m                          Query a domain using default settings\n  \x1b[1mdog\x1b[0m \x1b[32mexample.net MX\x1b[0m                       ...looking up MX records instead\n  \x1b[1mdog\x1b[0m \x1b[32mexample.net MX @1.1.1.1\x1b[0m              ...using a specific nameserver instead\n  \x1b[1mdog\x1b[0m \x1b[32mexample.net MX @1.1.1.1\x1b[0m \x1b[1;33m-T\x1b[0m           ...using TCP rather than UDP\n  \x1b[1mdog\x1b[0m \x1b[1;33m-q\x1b[0m \x1b[33mexample.net\x1b[0m \x1b[1;33m-t\x1b[0m \x1b[33mMX\u{1b}[0m \u{1b}[1;33m-n\u{1b}[0m \u{1b}[33m1.1.1.1\u{1b}[0m \u{1b}[1;33m-T\u{1b}[0m   As above, but using explicit arguments\n\n\u{1b}[4mQuery options:\u{1b}[0m\n  \u{1b}[32m<arguments>\u{1b}[0m              Human-readable host names, nameservers, types, or classes\n  \u{1b}[1;33m-q\u{1b}[0m, \u{1b}[1;33m--query\u{1b}[0m=\u{1b}[33mHOST\u{1b}[0m         Host name or domain name to query\n  \u{1b}[1;33m-t\u{1b}[0m, \u{1b}[1;33m--type\u{1b}[0m=\u{1b}[33mTYPE\u{1b}[0m          Type of the DNS record being queried (A, MX, NS...)\n  \u{1b}[1;33m-n\u{1b}[0m, \u{1b}[1;33m--nameserver\u{1b}[0m=\u{1b}[33mADDR\u{1b}[0m    Address of the nameserver to send packets to\n  \u{1b}[1;33m--class\u{1b}[0m=\u{1b}[33mCLASS\u{1b}[0m            Network class of the DNS record being queried (IN, CH, HS)\n\n\u{1b}[4mSending options:\u{1b}[0m\n  \u{1b}[1;33m--edns\u{1b}[0m=\u{1b}[33mSETTING\u{1b}[0m           Whether to OPT in to EDNS (disable, hide, show)\n  \u{1b}[1;33m--txid\u{1b}[0m=\u{1b}[33mNUMBER\u{1b}[0m            Set the transaction ID to a specific value\n  \u{1b}[1;33m-Z\u{1b}[0m=\u{1b}[33mTWEAKS\u{1b}[0m                Set uncommon protocol-level tweaks\n\n\u{1b}[4mProtocol options:\u{1b}[0m\n  \u{1b}[1;33m-U\u{1b}[0m, \u{1b}[1;33m--udp\u{1b}[0m                Use the DNS protocol over UDP\n  \u{1b}[1;33m-T\u{1b}[0m, \u{1b}[1;33m--tcp\u{1b}[0m                Use the DNS protocol over TCP\n  \u{1b}[1;33m-S\u{1b}[0m, \u{1b}[1;33m--tls\u{1b}[0m                Use the DNS-over-TLS protocol\n  \u{1b}[1;33m-H\u{1b}[0m, \u{1b}[1;33m--https\u{1b}[0m              Use the DNS-over-HTTPS protocol\n\n\u{1b}[4mOutput options:\u{1b}[0m\n  \u{1b}[1;33m-1\u{1b}[0m, \u{1b}[1;33m--short\u{1b}[0m              Short mode: display nothing but the first result\n  \u{1b}[1;33m-J\u{1b}[0m, \u{1b}[1;33m--json\u{1b}[0m               Display the output as JSON\n  \u{1b}[1;33m--color\u{1b}[0m, \u{1b}[1;33m--colour\u{1b}[0m=\u{1b}[33mWHEN\u{1b}[0m   When to colourise the output (always, automatic, never)\n  \u{1b}[1;33m--seconds\u{1b}[0m                Do not format durations, display them as seconds\n  \u{1b}[1;33m--time\u{1b}[0m                   Print how long the response took to arrive\n\n\u{1b}[4mMeta options:\u{1b}[0m\n  \u{1b}[1;33m-?\u{1b}[0m, \u{1b}[1;33m--help\u{1b}[0m               Print list of command-line options\n  \u{1b}[1;33m-v\u{1b}[0m, \u{1b}[1;33m--version\u{1b}[0m            Print version information\n";

fn main() {
    let raw_args: Vec<String> = std::env::args().skip(1).collect();

    #[derive(Debug, Clone, PartialEq, Eq)]
    enum ColorMode { Always, Automatic, Never }

    #[derive(Default)]
    struct Seen {
        query: Vec<String>,
        qtype: Vec<String>,
        nameserver: Vec<String>,
        class: Vec<String>,
        edns: Option<String>,
        txid: Option<String>,
        tweaks: Vec<String>,
        udp: bool, tcp: bool, tls: bool, https: bool,
        short: bool, json: bool,
        color: Option<String>,
        colour: Option<String>,
        seconds: bool, time: bool,
        help: bool, version: bool,
    }

    let mut seen = Seen::default();
    let mut bare_args: Vec<String> = Vec::new();
    let mut error: Option<String> = None;
    let mut i = 0;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "--" {
            i+=1;
            while i < raw_args.len() {
                bare_args.push(raw_args[i].clone());
                i+=1;
            }
            break;
        } else if arg.starts_with("--") {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos+1..];
                match name {
                    "--query" => seen.query.push(value.to_string()),
                    "--type" => seen.qtype.push(value.to_string()),
                    "--nameserver" => seen.nameserver.push(value.to_string()),
                    "--class" => seen.class.push(value.to_string()),
                    "--edns" => {
                        if seen.edns.is_some() { error = Some("Option 'edns' given more than once".into()); break; }
                        seen.edns = Some(value.to_string());
                    }
                    "--txid" => {
                        if seen.txid.is_some() { error = Some("Option 'txid' given more than once".into()); break; }
                        seen.txid = Some(value.to_string());
                    }
                    "--color" => {
                        if seen.color.is_some() { error = Some("Option 'color' given more than once".into()); break; }
                        seen.color = Some(value.to_string());
                    }
                    "--colour" => {
                        if seen.colour.is_some() { error = Some("Option 'colour' given more than once".into()); break; }
                        seen.colour = Some(value.to_string());
                    }
                    _ => {
                        let opt = &name[2..];
                        error = Some(format!("Unrecognized option: '{}'", opt));
                        break;
                    }
                }
                i+=1;
            } else {
                match arg.as_str() {
                    "--query" => {
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'query' missing".into()); break; }
                        seen.query.push(raw_args[i+1].clone()); i+=2;
                    }
                    "--type" => {
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'type' missing".into()); break; }
                        seen.qtype.push(raw_args[i+1].clone()); i+=2;
                    }
                    "--nameserver" => {
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'nameserver' missing".into()); break; }
                        seen.nameserver.push(raw_args[i+1].clone()); i+=2;
                    }
                    "--class" => {
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'class' missing".into()); break; }
                        seen.class.push(raw_args[i+1].clone()); i+=2;
                    }
                    "--edns" => {
                        if seen.edns.is_some() { error = Some("Option 'edns' given more than once".into()); break; }
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'edns' missing".into()); break; }
                        seen.edns = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--txid" => {
                        if seen.txid.is_some() { error = Some("Option 'txid' given more than once".into()); break; }
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'txid' missing".into()); break; }
                        seen.txid = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--color" => {
                        if seen.color.is_some() { error = Some("Option 'color' given more than once".into()); break; }
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'color' missing".into()); break; }
                        seen.color = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--colour" => {
                        if seen.colour.is_some() { error = Some("Option 'colour' given more than once".into()); break; }
                        if i+1 >= raw_args.len() { error = Some("Argument to option 'colour' missing".into()); break; }
                        seen.colour = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--udp" => {
                        if seen.udp { error = Some("Option 'udp' given more than once".into()); break; }
                        seen.udp = true; i+=1;
                    }
                    "--tcp" => {
                        if seen.tcp { error = Some("Option 'tcp' given more than once".into()); break; }
                        seen.tcp = true; i+=1;
                    }
                    "--tls" => {
                        if seen.tls { error = Some("Option 'tls' given more than once".into()); break; }
                        seen.tls = true; i+=1;
                    }
                    "--https" => {
                        if seen.https { error = Some("Option 'https' given more than once".into()); break; }
                        seen.https = true; i+=1;
                    }
                    "--short" => {
                        if seen.short { error = Some("Option 'short' given more than once".into()); break; }
                        seen.short = true; i+=1;
                    }
                    "--json" => {
                        if seen.json { error = Some("Option 'json' given more than once".into()); break; }
                        seen.json = true; i+=1;
                    }
                    "--seconds" => {
                        if seen.seconds { error = Some("Option 'seconds' given more than once".into()); break; }
                        seen.seconds = true; i+=1;
                    }
                    "--time" => {
                        if seen.time { error = Some("Option 'time' given more than once".into()); break; }
                        seen.time = true; i+=1;
                    }
                    "--help" => {
                        if seen.help { error = Some("Option 'help' given more than once".into()); break; }
                        seen.help = true; i+=1;
                    }
                    "--version" => {
                        if seen.version { error = Some("Option 'version' given more than once".into()); break; }
                        seen.version = true; i+=1;
                    }
                    _ => {
                        let opt = &arg[2..];
                        error = Some(format!("Unrecognized option: '{}'", opt));
                        break;
                    }
                }
            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'q' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            seen.query.push(rest);
                            break;
                        } else {
                            if i+1 >= raw_args.len() { error = Some("Argument to option 'q' missing".into()); break; }
                            seen.query.push(raw_args[i+1].clone());
                            consumed_next = true;
                            break;
                        }
                    }
                    't' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            seen.qtype.push(rest);
                            break;
                        } else {
                            if i+1 >= raw_args.len() { error = Some("Argument to option 't' missing".into()); break; }
                            seen.qtype.push(raw_args[i+1].clone());
                            consumed_next = true;
                            break;
                        }
                    }
                    'n' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            seen.nameserver.push(rest);
                            break;
                        } else {
                            if i+1 >= raw_args.len() { error = Some("Argument to option 'n' missing".into()); break; }
                            seen.nameserver.push(raw_args[i+1].clone());
                            consumed_next = true;
                            break;
                        }
                    }
                    'Z' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            seen.tweaks.push(rest);
                            break;
                        } else {
                            if i+1 >= raw_args.len() { error = Some("Argument to option 'Z' missing".into()); break; }
                            seen.tweaks.push(raw_args[i+1].clone());
                            consumed_next = true;
                            break;
                        }
                    }
                    'U' => {
                        if seen.udp { error = Some("Option 'udp' given more than once".into()); break; }
                        seen.udp = true; j+=1; continue;
                    }
                    'T' => {
                        if seen.tcp { error = Some("Option 'tcp' given more than once".into()); break; }
                        seen.tcp = true; j+=1; continue;
                    }
                    'S' => {
                        if seen.tls { error = Some("Option 'tls' given more than once".into()); break; }
                        seen.tls = true; j+=1; continue;
                    }
                    'H' => {
                        if seen.https { error = Some("Option 'https' given more than once".into()); break; }
                        seen.https = true; j+=1; continue;
                    }
                    '1' => {
                        if seen.short { error = Some("Option 'short' given more than once".into()); break; }
                        seen.short = true; j+=1; continue;
                    }
                    'J' => {
                        if seen.json { error = Some("Option 'json' given more than once".into()); break; }
                        seen.json = true; j+=1; continue;
                    }
                    '?' => {
                        if seen.help { error = Some("Option 'help' given more than once".into()); break; }
                        seen.help = true; j+=1; continue;
                    }
                    'v' => {
                        if seen.version { error = Some("Option 'version' given more than once".into()); break; }
                        seen.version = true; j+=1; continue;
                    }
                    _ => {
                        error = Some(format!("Unrecognized option: '{}'", c));
                        break;
                    }
                }
            }
            if error.is_some() { break; }
            i+=1;
            if consumed_next { i+=1; }
        } else {
            bare_args.push(arg.clone());
            i+=1;
        }
    }

    if let Some(err) = error {
        eprintln!("dog: Invalid options: {}", err);
        std::process::exit(3);
    }

    // color determination
    let mut final_mode = ColorMode::Automatic;
    // color takes precedence over colour
    if let Some(v) = seen.color.as_ref() {
        match v.as_str() {
            "always" => final_mode = ColorMode::Always,
            "never" => final_mode = ColorMode::Never,
            "automatic" => final_mode = ColorMode::Automatic,
            _ => final_mode = ColorMode::Automatic,
        }
    } else if let Some(v) = seen.colour.as_ref() {
        match v.as_str() {
            "always" => final_mode = ColorMode::Always,
            "never" => final_mode = ColorMode::Never,
            "automatic" => final_mode = ColorMode::Automatic,
            _ => final_mode = ColorMode::Automatic,
        }
    } else {
        final_mode = ColorMode::Automatic;
    }

    let use_color = match final_mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Automatic => std::io::stdout().is_terminal(),
    };

    if seen.version {
        if use_color {
            println!("dog \x1b[1;32m●\x1b[0m command-line DNS client");
            println!("v0.2.0-pre [d436ea3b] built on 2026-08-10 \x1b[1;31m(pre-release!)\x1b[0m");
            println!("\x1b[1;4;34mhttps://dns.lookup.dog/\x1b[0m");
        } else {
            println!("dog ● command-line DNS client");
            println!("v0.2.0-pre [d436ea3b] built on 2026-08-10 (pre-release!)");
            println!("mhttps://dns.lookup.dog/");
        }
        std::process::exit(0);
    }
    if seen.help {
        if use_color {
            // Use HELP_ALWAYS but need to ensure it matches original's help always (we have placeholder, but better to read from captured file? We'll embed exact from original)
            // For now, if use_color, we will attempt to reconstruct with exact same as original's always version
            // The HELP_ALWAYS we defined is slightly off (we have some \u escapes that may be wrong). Let's instead output help never for both? But we need colors.
            // We'll use a simpler approach: generate help with colors programmatically to match original's structure.
            print!("{}", HELP_ALWAYS);
        } else {
            print!("{}", HELP_NEVER);
        }
        std::process::exit(0);
    }

    // Validation for other options
    let valid_types = ["A","AAAA","AFSDB","ANY","APL","AXFR","CAA","CDNSKEY","CDS","CERT","CNAME","CSYNC","DHCID","DLV","DNAME","DS","HINFO","HIP","IPSECKEY","IXFR","KEY","KX","LOC","MX","NAPTR","NS","NSEC","NSEC3","NSEC3PARAM","OPENPGPKEY","OPT","PTR","RP","RRSIG","SIG","SMIMEA","SOA","SRV","SSHFP","TA","TKEY","TLSA","TSIG","TXT","URI","EUI48","EUI64"];

    let mut domains: Vec<String> = Vec::new();
    let mut types: Vec<String> = Vec::new();
    let mut classes: Vec<String> = Vec::new();
    let mut nameservers: Vec<String> = Vec::new();

    for q in &seen.query { domains.push(q.clone()); }
    for t in &seen.qtype {
        if t.is_empty() { eprintln!("dog: Invalid options: Invalid query type \"{}\"", t); std::process::exit(3); }
        let up = t.to_uppercase();
        if !valid_types.contains(&up.as_str()) { eprintln!("dog: Invalid options: Invalid query type \"{}\"", t); std::process::exit(3); }
        types.push(up);
    }
    for n in &seen.nameserver { nameservers.push(n.clone()); }
    for c in &seen.class {
        if c.is_empty() { eprintln!("dog: Invalid options: Invalid query class \"{}\"", c); std::process::exit(3); }
        let up = c.to_uppercase();
        if !["IN","CH","HS"].contains(&up.as_str()) { eprintln!("dog: Invalid options: Invalid query class \"{}\"", c); std::process::exit(3); }
        classes.push(up);
    }

    for bare in &bare_args {
        if bare.starts_with('@') {
            nameservers.push(bare[1..].to_string());
        } else {
            let up = bare.to_uppercase();
            if valid_types.contains(&up.as_str()) {
                types.push(up);
            } else if ["IN","CH","HS"].contains(&up.as_str()) {
                classes.push(up);
            } else {
                if bare.starts_with('-') {
                    eprintln!("dog: Invalid options: Invalid domain \"{}\"", bare);
                    std::process::exit(3);
                }
                domains.push(bare.clone());
            }
        }
    }

    if domains.is_empty() {
        // No domain => help exit 3
        if use_color {
            print!("{}", HELP_ALWAYS);
        } else {
            print!("{}", HELP_NEVER);
        }
        std::process::exit(3);
    }

    if types.is_empty() { types.push("A".into()); }
    if classes.is_empty() { classes.push("IN".into()); }

    // edns validation
    let edns_mode = match seen.edns.as_deref() {
        Some("disable") => "disable",
        Some("hide") => "hide",
        Some("show") => "show",
        Some(v) => { eprintln!("dog: Invalid options: Invalid EDNS setting \"{}\"", v); std::process::exit(3); }
        None => "hide",
    };

    // txid validation
    let txid_val: Option<u16> = match seen.txid.as_deref() {
        Some(s) => {
            match s.parse::<u32>() {
                Ok(n) if n <= 65535 => Some(n as u16),
                _ => { eprintln!("dog: Invalid options: Invalid transaction ID \"{}\"", s); std::process::exit(3); }
            }
        }
        None => None,
    };

    // Z tweaks validation
    let mut tweak_aa = false;
    let mut tweak_ad = false;
    let mut tweak_cd = false;
    let mut tweak_bufsize: Option<u16> = None;
    for tw in &seen.tweaks {
        if tw.is_empty() { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
        match tw.as_str() {
            "aa" => tweak_aa = true,
            "ad" => tweak_ad = true,
            "cd" => tweak_cd = true,
            _ if tw.starts_with("bufsize=") => {
                let v = &tw["bufsize=".len()..];
                if v.is_empty() { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
                match v.parse::<u32>() {
                    Ok(n) if n <= 65535 => tweak_bufsize = Some(n as u16),
                    _ => { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
                }
            }
            _ => { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
        }
    }

    // transport list
    let mut transports: Vec<&str> = Vec::new();
    if seen.udp { transports.push("udp"); }
    if seen.tcp { transports.push("tcp"); }
    if seen.tls { transports.push("tls"); }
    if seen.https { transports.push("https"); }
    if transports.is_empty() { transports.push("auto"); }

    // HTTPS requires URL nameserver
    if transports.contains(&"https") {
        let has_url = nameservers.iter().any(|ns| ns.starts_with("https://") || ns.starts_with("http://"));
        if !has_url {
            eprintln!("dog: Invalid options: You must pass a URL as a nameserver when using --https");
            std::process::exit(3);
        }
    }

    // For each combination, we need to perform query
    // For simplicity, we will generate queries in order: domains outer, types inner, classes inner, nameservers inner, transports inner
    // That's what earlier observed: domain outer, type inner for two domains and two types gave domain-major order.

    // We'll implement DNS query via UDP using std sockets and manual packet building.

    // Helper to build packet
    fn build_query(txid: u16, domain: &str, qtype_num: u16, qclass_num: u16, edns: &str, bufsize: Option<u16>, aa: bool, ad: bool, cd: bool) -> Vec<u8> {
        let mut packet = Vec::new();
        packet.extend_from_slice(&txid.to_be_bytes());
        let mut flags: u16 = 0x0100; // RD=1
        if aa { flags |= 0x0400; }
        if ad { flags |= 0x0020; }
        if cd { flags |= 0x0010; }
        packet.extend_from_slice(&flags.to_be_bytes());
        packet.extend_from_slice(&1u16.to_be_bytes()); // QD
        packet.extend_from_slice(&0u16.to_be_bytes()); // AN
        packet.extend_from_slice(&0u16.to_be_bytes()); // NS
        let arcount = if edns == "disable" { 0 } else { 1 };
        packet.extend_from_slice(&(arcount as u16).to_be_bytes());
        // QNAME
        // Split domain by '.' and encode, ignoring empty labels? But keep behavior for "example..com" => treat as example.com (skip empty)
        // Also for trailing dot: strip empties
        let trimmed = domain.trim_end_matches('.');
        if trimmed.is_empty() {
            // root?
            packet.push(0);
        } else {
            for label in trimmed.split('.') {
                if label.is_empty() { continue; }
                // For simplicity, length must be <=63
                packet.push(label.len() as u8);
                packet.extend_from_slice(label.as_bytes());
            }
            packet.push(0);
        }
        packet.extend_from_slice(&qtype_num.to_be_bytes());
        packet.extend_from_slice(&qclass_num.to_be_bytes());
        if arcount == 1 {
            // OPT record
            packet.push(0); // root name
            packet.extend_from_slice(&41u16.to_be_bytes()); // OPT
            let payload = bufsize.unwrap_or(4096);
            packet.extend_from_slice(&payload.to_be_bytes()); // UDP payload size in class field
            packet.extend_from_slice(&0u32.to_be_bytes()); // extended rcode + version + Z
            packet.extend_from_slice(&0u16.to_be_bytes()); // rdlen
        }
        packet
    }

