    // Helper to resolve nameserver string to SocketAddr
    fn resolve_ns(ns_str: &str) -> Result<SocketAddr, String> {
        // Check if it's URL for https (should not happen here for udp/tcp)
        if ns_str.starts_with("https://") || ns_str.starts_with("http://") {
            return Err(format!("URL not supported for this transport"));
        }
        // Check for port
        if let Some(colon_pos) = ns_str.rfind(':') {
            // Could be IPv6 in brackets or plain
            let after = &ns_str[colon_pos+1..];
            if after.parse::<u16>().is_ok() {
                let ip_part = &ns_str[..colon_pos];
                // Remove brackets for IPv6
                let ip_clean = ip_part.trim_matches(|c| c=='[' || c==']');
                if let Ok(ip) = ip_clean.parse::<std::net::IpAddr>() {
                    return Ok(SocketAddr::new(ip, after.parse::<u16>().unwrap()));
                } else {
                    // Try to resolve hostname with port via getaddrinfo? Use ToSocketAddrs
                    // For simplicity, try format ip_clean:port
                    let addr_str = format!("{}:{}", ip_clean, after);
                    match addr_str.to_socket_addrs() {
                        Ok(mut iter) => {
                            if let Some(sa) = iter.next() {
                                return Ok(sa);
                            } else {
                                return Err(format!("failed to lookup address information: Name or service not known"));
                            }
                        }
                        Err(_e) => {
                            return Err(format!("failed to lookup address information: Name or service not known"));
                        }
                    }
                }
            }
        }
        // No port, try parse IP
        if let Ok(ip) = ns_str.parse::<std::net::IpAddr>() {
            return Ok(SocketAddr::new(ip, 53));
        }
        // Try as hostname, port 53
        let addr_str = format!("{}:53", ns_str);
        match addr_str.to_socket_addrs() {
            Ok(mut iter) => {
                if let Some(sa) = iter.next() {
                    Ok(sa)
                } else {
                    Err(format!("failed to lookup address information: Name or service not known"))
                }
            }
            Err(_e) => {
                // Check for invalid port value case: if ns_str contains : and after not numeric, error "invalid port value"
                if ns_str.contains(':') {
                    let after = ns_str.rsplit(':').next().unwrap_or("");
                    if !after.is_empty() && after.parse::<u16>().is_err() {
                        return Err(format!("invalid port value"));
                    }
                }
                Err(format!("failed to lookup address information: Name or service not known"))
            }
        }
    }

    // DNS query function via UDP
    fn query_udp(packet: &[u8], sock_addr: SocketAddr) -> Result<Vec<u8>, String> {
        use std::net::UdpSocket;
        let sock = UdpSocket::bind("0.0.0.0:0").map_err(|e| e.to_string())?;
        sock.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
        sock.set_write_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
        sock.send_to(packet, sock_addr).map_err(|e| e.to_string())?;
        let mut buf = [0u8; 4096];
        let (len, _) = sock.recv_from(&mut buf).map_err(|e| e.to_string())?;
        Ok(buf[..len].to_vec())
    }

    fn query_tcp(packet: &[u8], sock_addr: SocketAddr) -> Result<Vec<u8>, String> {
        use std::net::TcpStream;
        use std::io::{Read, Write};
        let mut stream = TcpStream::connect_timeout(&sock_addr, Duration::from_secs(5)).map_err(|e| e.to_string())?;
        stream.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
        stream.set_write_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
        let len = packet.len() as u16;
        stream.write_all(&len.to_be_bytes()).map_err(|e| e.to_string())?;
        stream.write_all(packet).map_err(|e| e.to_string())?;
        let mut len_buf = [0u8; 2];
        stream.read_exact(&mut len_buf).map_err(|e| e.to_string())?;
        let resp_len = u16::from_be_bytes(len_buf) as usize;
        let mut buf = vec![0u8; resp_len];
        stream.read_exact(&mut buf).map_err(|e| e.to_string())?;
        Ok(buf)
    }

    // For parsing responses, implement simple parser for our needed types
    fn parse_response(data: &[u8], query_domain: &str, query_type_str: &str, query_class_str: &str, edns_mode: &str) -> Result<(DnsResponse, bool), String> {
        use std::convert::TryInto;
        if data.len() < 12 { return Err("insufficient data".to_string()); }
        let txid = u16::from_be_bytes([data[0], data[1]]);
        let flags = u16::from_be_bytes([data[2], data[3]]);
        let qdcount = u16::from_be_bytes([data[4], data[5]]);
        let ancount = u16::from_be_bytes([data[6], data[7]]);
        let nscount = u16::from_be_bytes([data[8], data[9]]);
        let arcount = u16::from_be_bytes([data[10], data[11]]);
        let rcode = flags & 0x000F;
        let is_nx = rcode == 3;

        let mut offset = 12usize;
        let mut queries = Vec::new();
        for _ in 0..qdcount {
            let (qname, new_off) = parse_name(data, offset);
            offset = new_off;
            if offset+4 > data.len() { return Err("insufficient data".to_string()); }
            let qtype = u16::from_be_bytes([data[offset], data[offset+1]]);
            let qclass = u16::from_be_bytes([data[offset+2], data[offset+3]]);
            offset += 4;
            // For JSON, we need to produce query with name as in original: ensure trailing dot
            // Use qname as parsed (already has trailing dot)
            let type_str = match qtype {
                1 => "A", 2 => "NS", 5 => "CNAME", 6 => "SOA", 12 => "PTR", 13 => "HINFO", 15 => "MX", 16 => "TXT", 17 => "RP", 18 => "AFSDB", 24 => "SIG", 25 => "KEY", 28 => "AAAA", 29 => "LOC", 33 => "SRV", 35 => "NAPTR", 36 => "KX", 37 => "CERT", 39 => "DNAME", 41 => "OPT", 42 => "APL", 43 => "DS", 44 => "SSHFP", 45 => "IPSECKEY", 46 => "RRSIG", 47 => "NSEC", 49 => "DHCID", 50 => "NSEC3", 51 => "NSEC3PARAM", 52 => "TLSA", 53 => "SMIMEA", 55 => "HIP", 59 => "CDS", 60 => "CDNSKEY", 61 => "OPENPGPKEY", 62 => "CSYNC", 108 => "EUI48", 109 => "EUI64", 249 => "TKEY", 250 => "TSIG", 251 => "IXFR", 252 => "AXFR", 255 => "ANY", 256 => "URI", 257 => "CAA", 32768 => "TA", 32769 => "DLV", _ => "UNKNOWN"
            };
            let class_str = match qclass { 1 => "IN", 3 => "CH", 4 => "HS", _ => "IN" };
            queries.push(serde_json::json!({"name": qname, "class": class_str, "type": type_str}));
        }

        let mut answers = Vec::new();
        let mut authorities = Vec::new();
        let mut additionals = Vec::new();

        fn parse_rdata(data: &[u8], offset: usize, rdlen: usize, type_num: u16) -> (serde_json::Value, String, String, usize) {
            // Returns (json, text, short, new_offset)
            let end = offset + rdlen;
            if end > data.len() {
                return (serde_json::json!({"bytes": []}), "".to_string(), "".to_string(), end);
            }
            let rdata_slice = &data[offset..end];
            match type_num {
                1 => { // A
                    if rdlen == 4 {
                        let ip = format!("{}.{}.{}.{}", rdata_slice[0], rdata_slice[1], rdata_slice[2], rdata_slice[3]);
                        (serde_json::json!({"address": ip}), ip.clone(), ip, end)
                    } else {
                        (serde_json::json!({"bytes": rdata_slice}), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), end)
                    }
                }
                28 => { // AAAA
                    if rdlen == 16 {
                        let ip = std::net::Ipv6Addr::from(<[u8;16]>::try_from(rdata_slice).unwrap()).to_string();
                        (serde_json::json!({"address": ip}), ip.clone(), ip, end)
                    } else {
                        (serde_json::json!({"bytes": rdata_slice}), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), end)
                    }
                }
                5 => { // CNAME
                    let (name, _) = parse_name(data, offset);
                    (serde_json::json!({"domain": name}), format!("\"{}\"", name), format!("\"{}\"", name), end)
                }
                2 => { // NS
                    let (name, _) = parse_name(data, offset);
                    (serde_json::json!({"nameserver": name}), format!("\"{}\"", name), format!("\"{}\"", name), end)
                }
                12 => { // PTR
                    let (name, _) = parse_name(data, offset);
                    (serde_json::json!({"cname": name}), format!("\"{}\"", name), format!("\"{}\"", name), end)
                }
                15 => { // MX
                    if rdlen >= 2 {
                        let pref = u16::from_be_bytes([rdata_slice[0], rdata_slice[1]]);
                        let (exchange, _) = parse_name(data, offset+2);
                        let exchange_display = if exchange.is_empty() { "\"\"".to_string() } else { format!("\"{}\"", exchange) };
                        (serde_json::json!({"preference": pref, "exchange": exchange}), format!("{} {}", pref, exchange_display), format!("{} {}", pref, exchange_display), end)
                    } else {
                        (serde_json::json!({"bytes": rdata_slice}), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), end)
                    }
                }
                16 => { // TXT
                    let mut msgs = Vec::new();
                    let mut off = 0;
                    while off < rdata_slice.len() {
                        let l = rdata_slice[off] as usize;
                        off+=1;
                        if off+l > rdata_slice.len() { break; }
                        let txt = String::from_utf8_lossy(&rdata_slice[off..off+l]).to_string();
                        msgs.push(txt);
                        off+=l;
                    }
                    let json = serde_json::json!({"messages": msgs});
                    let text = msgs.iter().map(|m| format!("\"{}\"", m)).collect::<Vec<_>>().join(" ");
                    // For short, first? Actually short outputs messages as space separated quoted? For TXT with one message, short is "\"hello world\"" . For multiple messages? Dog displays each TXT as separate answer? Each answer contains one TXT with maybe multiple character strings? The text output for TXT with multiple messages per record? Earlier TXT example.com had two separate TXT answers each with one message. The text output for each was separate line with quoted string.
                    // For our simple, if multiple strings, join with space?
                    let short = msgs.iter().map(|m| format!("\"{}\"", m)).collect::<Vec<_>>().join(" ");
                    (json, text, short, end)
                }
                6 => { // SOA
                    // SOA: mname, rname, serial, refresh, retry, expire, minimum
                    let (mname, off1) = parse_name(data, offset);
                    let (rname, off2) = parse_name(data, off1);
                    let mut cur = off2;
                    if cur + 20 > data.len() {
                        return (serde_json::json!({"mname": mname}), format!("\"{}\"", mname), format!("\"{}\"", mname), end);
                    }
                    let serial = u32::from_be_bytes([data[cur], data[cur+1], data[cur+2], data[cur+3]]);
                    let refresh = u32::from_be_bytes([data[cur+4], data[cur+5], data[cur+6], data[cur+7]]);
                    let retry = u32::from_be_bytes([data[cur+8], data[cur+9], data[cur+10], data[cur+11]]);
                    let expire = u32::from_be_bytes([data[cur+12], data[cur+13], data[cur+14], data[cur+15]]);
                    let minimum = u32::from_be_bytes([data[cur+16], data[cur+17], data[cur+18], data[cur+19]]);
                    // For JSON, original dog's SOA json only contains mname? From earlier examples, SOA json data only had mname field: {"mname":"..."} – not full SOA. Let's replicate that: only mname.
                    let json = serde_json::json!({"mname": mname});
                    // Text: "mname" "rname" serial refresh retry expire min (with durations formatted)
                    // We'll need to format refresh etc as durations later outside? But for now produce text with raw seconds? Actually text uses formatted durations for refresh etc (e.g., 900 => 15m00s)
                    // We'll produce placeholder and let caller format.
                    // For now, produce text that will be formatted later using fmt_ttl
                    // We need to capture all fields for text formatting
                    // We'll store as json but also produce text string with formatting using fmt_ttl for those intervals
                    // To keep simple, produce text with formatted durations using our fmt_ttl function (which we need accessible)
                    // We'll do formatting here as well
                    let fmt = |v: u32| {
                        let d = v / 86400;
                        let h = (v % 86400) / 3600;
                        let m = (v % 3600) / 60;
                        let s = v % 60;
                        if d>0 { format!("{}d{}h{:02}m{:02}s", d, h, m, s) }
                        else if h>0 { format!("{}h{:02}m{:02}s", h, m, s) }
                        else if m>0 { format!("{}m{:02}s", m, s) }
                        else { format!("{}s", s) }
                    };
                    let text = format!("\"{}\" \"{}\" {} {} {} {} {}", mname, rname, serial, fmt(refresh), fmt(retry), fmt(expire), fmt(minimum));
                    let short = text.clone();
                    (json, text, short, end)
                }
                33 => { // SRV
                    if rdlen >= 6 {
                        let priority = u16::from_be_bytes([rdata_slice[0], rdata_slice[1]]);
                        let weight = u16::from_be_bytes([rdata_slice[2], rdata_slice[3]]);
                        let port = u16::from_be_bytes([rdata_slice[4], rdata_slice[5]]);
                        let (target, _) = parse_name(data, offset+6);
                        let json = serde_json::json!({"priority": priority, "weight": weight, "port": port, "target": target});
                        let text = format!("{} {} \"{}\":{}", priority, weight, target, port);
                        let short = text.clone();
                        (json, text, short, end)
                    } else {
                        (serde_json::json!({"bytes": rdata_slice}), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), format!("[{}]", rdata_slice.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(", ")), end)
                    }
                }
                35 => { // NAPTR
                    if rdlen >= 2 {
                        let order = u16::from_be_bytes([rdata_slice[0], rdata_slice[1]]);
                        let mut cur = 2;
                        if cur >= rdata_slice.len() { return (serde_json::json!({"bytes": rdata_slice}), "".into(), "".into(), end); }
                        let pref = if cur+1 < rdata_slice.len() { u16::from_be_bytes([rdata_slice[cur], rdata_slice[cur+1]]) } else { 0 };
                        cur+=2;
                        // flags length
                        if cur >= rdata_slice.len() { return (serde_json::json!({"bytes": rdata_slice}), "".into(), "".into(), end); }
                        let flags_len = rdata_slice[cur] as usize; cur+=1;
                        let flags = if cur+flags_len <= rdata_slice.len() { String::from_utf8_lossy(&rdata_slice[cur..cur+flags_len]).to_string() } else { "".to_string() };
                        cur+=flags_len;
                        if cur >= rdata_slice.len() { return (serde_json::json!({"bytes": rdata_slice}), "".into(), "".into(), end); }
                        let service_len = rdata_slice[cur] as usize; cur+=1;
                        let service = if cur+service_len <= rdata_slice.len() { String::from_utf8_lossy(&rdata_slice[cur..cur+service_len]).to_string() } else { "".to_string() };
                        cur+=service_len;
                        if cur >= rdata_slice.len() { return (serde_json::json!({"bytes": rdata_slice}), "".into(), "".into(), end); }
                        let regex_len = rdata_slice[cur] as usize; cur+=1;
                        let regex = if cur+regex_len <= rdata_slice.len() { String::from_utf8_lossy(&rdata_slice[cur..cur+regex_len]).to_string() } else { "".to_string() };
                        cur+=regex_len;
                        let replacement_off = offset + cur;
