            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'q' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            seen.query.push(rest);
                            break;
                        } else {
                            if i+1 >= raw_args.len() { error = Some("Argument to option 'q' missing".into()); break; }
                            seen.query.push(raw_args[i+1].clone());
                            consumed_next = true;
