    fn parse_name(data: &[u8], mut offset: usize) -> (String, usize) {
        let mut labels: Vec<String> = Vec::new();
        let mut jumped = false;
        let mut jump_off = 0;
        let mut steps = 0;
        loop {
            if offset >= data.len() { break; }
            let len = data[offset];
            if len & 0xC0 == 0xC0 {
                // pointer
                if offset+1 >= data.len() { break; }
                let b2 = data[offset+1];
                let ptr = (((len as u16 & 0x3F) << 8) | b2 as u16) as usize;
                if !jumped {
                    jump_off = offset+2;
                }
                offset = ptr;
                jumped = true;
                steps+=1;
                if steps>20 { break; }
                continue;
            }
            if len == 0 {
                offset+=1;
                break;
            }
            offset+=1;
            if offset+len as usize > data.len() { break; }
            let label = String::from_utf8_lossy(&data[offset..offset+len as usize]).to_string();
            labels.push(label);
            offset += len as usize;
        }
        let name = if labels.is_empty() { "".to_string() } else { labels.join(".") + "." };
        if jumped {
            (name, jump_off)
        } else {
            (name, offset)
        }
    }

    // For text formatting of TTL
    fn fmt_ttl(ttl: u32, use_seconds: bool) -> String {
        if use_seconds {
            return ttl.to_string();
        }
        let d = ttl / 86400;
        let h = (ttl % 86400) / 3600;
        let m = (ttl % 3600) / 60;
        let s = ttl % 60;
        if d>0 {
            format!("{}d{}h{:02}m{:02}s", d, h, m, s)
        } else if h>0 {
            format!("{}h{:02}m{:02}s", h, m, s)
        } else if m>0 {
            format!("{}m{:02}s", m, s)
        } else {
            format!("{}s", s)
        }
    }

