fn fmt_ttl(ttl: u32, use_seconds: bool) -> String {
    if use_seconds { return ttl.to_string(); }
    let d = ttl / 86400;
    let h = (ttl % 86400) / 3600;
    let m = (ttl % 3600) / 60;
    let s = ttl % 60;
    if d > 0 { format!("{}d{}h{:02}m{:02}s", d, h, m, s) }
    else if h > 0 { format!("{}h{:02}m{:02}s", h, m, s) }
    else if m > 0 { format!("{}m{:02}s", m, s) }
    else { format!("{}s", s) }
}

fn load_hosts() -> HashMap<String, Vec<String>> {
    let mut map = HashMap::new();
    if let Ok(content) = std::fs::read_to_string("/etc/hosts") {
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') { continue; }
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() < 2 { continue; }
            let ip = parts[0];
            for host in &parts[1..] {
                map.entry(host.to_lowercase()).or_insert_with(Vec::new).push(ip.to_string());
            }
        }
    }
    map
}

fn parse_name(data: &[u8], mut offset: usize) -> (String, usize) {
    let mut labels = Vec::new();
    let mut jumped = false;
    let mut jump_off = 0;
    let mut steps = 0;
    loop {
        if offset >= data.len() { break; }
        let len = data[offset];
        if len & 0xC0 == 0xC0 {
            if offset+1 >= data.len() { break; }
            let b2 = data[offset+1];
            let ptr = (((len as u16 & 0x3F) << 8) | b2 as u16) as usize;
            if !jumped { jump_off = offset+2; }
            offset = ptr;
            jumped = true;
            steps+=1;
            if steps>100 { break; }
            continue;
        }
        if len == 0 { offset+=1; break; }
        offset+=1;
        if offset+len as usize > data.len() { break; }
        let label = String::from_utf8_lossy(&data[offset..offset+len as usize]).to_string();
        labels.push(label);
        offset+=len as usize;
    }
    let name = if labels.is_empty() { "".to_string() } else { labels.join(".") + "." };
    if jumped { (name, jump_off) } else { (name, offset) }
}

fn type_to_num(s: &str) -> u16 {
    match s {
        "A" => 1, "NS" => 2, "CNAME" => 5, "SOA" => 6, "PTR" => 12, "HINFO" => 13, "MX" => 15, "TXT" => 16, "RP" => 17, "AFSDB" => 18, "SIG" => 24, "KEY" => 25, "AAAA" => 28, "LOC" => 29, "SRV" => 33, "NAPTR" => 35, "KX" => 36, "CERT" => 37, "DNAME" => 39, "OPT" => 41, "APL" => 42, "DS" => 43, "SSHFP" => 44, "IPSECKEY" => 45, "RRSIG" => 46, "NSEC" => 47, "DHCID" => 49, "NSEC3" => 50, "NSEC3PARAM" => 51, "TLSA" => 52, "SMIMEA" => 53, "HIP" => 55, "CDS" => 59, "CDNSKEY" => 60, "OPENPGPKEY" => 61, "CSYNC" => 62, "EUI48" => 108, "EUI64" => 109, "TKEY" => 249, "TSIG" => 250, "IXFR" => 251, "AXFR" => 252, "ANY" => 255, "URI" => 256, "CAA" => 257, "TA" => 32768, "DLV" => 32769, _ => 1,
    }
}

fn class_to_num(s: &str) -> u16 { match s { "IN" => 1, "CH" => 3, "HS" => 4, _ => 1 } }

fn num_to_type(n: u16) -> String {
    match n {
        1 => "A", 2 => "NS", 5 => "CNAME", 6 => "SOA", 12 => "PTR", 13 => "HINFO", 15 => "MX", 16 => "TXT", 17 => "RP", 18 => "AFSDB", 24 => "SIG", 25 => "KEY", 28 => "AAAA", 29 => "LOC", 33 => "SRV", 35 => "NAPTR", 36 => "KX", 37 => "CERT", 39 => "DNAME", 41 => "OPT", 42 => "APL", 43 => "DS", 44 => "SSHFP", 45 => "IPSECKEY", 46 => "RRSIG", 47 => "NSEC", 49 => "DHCID", 50 => "NSEC3", 51 => "NSEC3PARAM", 52 => "TLSA", 53 => "SMIMEA", 55 => "HIP", 59 => "CDS", 60 => "CDNSKEY", 61 => "OPENPGPKEY", 62 => "CSYNC", 108 => "EUI48", 109 => "EUI64", 249 => "TKEY", 250 => "TSIG", 251 => "IXFR", 252 => "AXFR", 255 => "ANY", 256 => "URI", 257 => "CAA", 32768 => "TA", 32769 => "DLV", _ => "UNKNOWN",
    }.to_string()
}

fn num_to_class(n: u16) -> String { match n { 1 => "IN", 3 => "CH", 4 => "HS", _ => "IN" }.to_string() }

fn build_query(txid: u16, domain: &str, qtype_num: u16, qclass_num: u16, edns: &str, bufsize: Option<u16>, aa: bool, ad: bool, cd: bool) -> Vec<u8> {
    let mut packet = Vec::new();
    packet.extend_from_slice(&txid.to_be_bytes());
    let mut flags: u16 = 0x0100;
    if aa { flags |= 0x0400; }
    if ad { flags |= 0x0020; }
    if cd { flags |= 0x0010; }
    packet.extend_from_slice(&flags.to_be_bytes());
    packet.extend_from_slice(&1u16.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    let arcount = if edns == "disable" { 0 } else { 1 };
    packet.extend_from_slice(&(arcount as u16).to_be_bytes());
    let trimmed = domain.trim_end_matches('.');
    if trimmed.is_empty() { packet.push(0); }
    else {
        for label in trimmed.split('.') {
            if label.is_empty() { continue; }
            let b = label.as_bytes();
            packet.push(b.len() as u8);
            packet.extend_from_slice(b);
        }
        packet.push(0);
    }
    packet.extend_from_slice(&qtype_num.to_be_bytes());
    packet.extend_from_slice(&qclass_num.to_be_bytes());
    if arcount == 1 {
        packet.push(0);
        packet.extend_from_slice(&41u16.to_be_bytes());
        let payload = bufsize.unwrap_or(4096);
        packet.extend_from_slice(&payload.to_be_bytes());
        packet.extend_from_slice(&0u32.to_be_bytes());
        packet.extend_from_slice(&0u16.to_be_bytes());
    }
    packet
}

fn resolve_ns(ns_str: &str) -> Result<SocketAddr, String> {
    if ns_str.starts_with("https://") || ns_str.starts_with("http://") {
        return Err("URL not supported for this transport".into());
    }
    if let Some(colon_pos) = ns_str.rfind(':') {
        let after = &ns_str[colon_pos+1..];
        if after.parse::<u16>().is_ok() {
            let ip_part = &ns_str[..colon_pos];
            let ip_clean = ip_part.trim_matches(|c| c=='[' || c==']');
            if let Ok(ip) = ip_clean.parse::<IpAddr>() {
                return Ok(SocketAddr::new(ip, after.parse::<u16>().unwrap()));
            } else {
                let addr_str = format!("{}:{}", ip_clean, after);
                match addr_str.to_socket_addrs() {
                    Ok(mut it) => {
                        if let Some(sa) = it.next() { return Ok(sa); }
                        else { return Err("failed to lookup address information: Name or service not known".into()); }
                    }
                    Err(_) => { return Err("failed to lookup address information: Name or service not known".into()); }
                }
            }
        }
    }
    if let Ok(ip) = ns_str.parse::<IpAddr>() {
        return Ok(SocketAddr::new(ip, 53));
    }
    let addr_str = format!("{}:53", ns_str);
    match addr_str.to_socket_addrs() {
        Ok(mut it) => {
            if let Some(sa) = it.next() { Ok(sa) } else { Err("failed to lookup address information: Name or service not known".into()) }
        }
        Err(_) => {
            if ns_str.contains(':') {
                let after = ns_str.rsplit(':').next().unwrap_or("");
                if !after.is_empty() && after.parse::<u16>().is_err() {
                    return Err("invalid port value".into());
                }
            }
            Err("failed to lookup address information: Name or service not known".into())
        }
    }
}

fn query_udp(packet: &[u8], sock_addr: SocketAddr) -> Result<Vec<u8>, String> {
    use std::net::UdpSocket;
    let sock = UdpSocket::bind("0.0.0.0:0").map_err(|e| e.to_string())?;
    sock.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    sock.set_write_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    sock.send_to(packet, sock_addr).map_err(|e| e.to_string())?;
    let mut buf = [0u8; 4096];
    let (len, _) = sock.recv_from(&mut buf).map_err(|e| e.to_string())?;
    Ok(buf[..len].to_vec())
}

fn query_tcp(packet: &[u8], sock_addr: SocketAddr) -> Result<Vec<u8>, String> {
    use std::net::TcpStream;
    use std::io::{Read, Write};
    let mut stream = TcpStream::connect_timeout(&sock_addr, Duration::from_secs(5)).map_err(|e| e.to_string())?;
    stream.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    stream.set_write_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    let len = packet.len() as u16;
    stream.write_all(&len.to_be_bytes()).map_err(|e| e.to_string())?;
    stream.write_all(packet).map_err(|e| e.to_string())?;
    let mut len_buf = [0u8; 2];
    stream.read_exact(&mut len_buf).map_err(|e| e.to_string())?;
    let resp_len = u16::from_be_bytes(len_buf) as usize;
    let mut buf = vec![0u8; resp_len];
    stream.read_exact(&mut buf).map_err(|e| e.to_string())?;
    Ok(buf)
}

struct DnsAnswer {
    name: String,
    class: String,
    ttl: u32,
    type_str: String,
    data_json: String,
    text_data: String,
    short_data: String,
}

struct DnsResponse {
    queries_json: String,
    answers: Vec<DnsAnswer>,
    authorities: Vec<DnsAnswer>,
    additionals: Vec<DnsAnswer>,
    has_nx: bool,
}

fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::new();
    for b in bytes { s.push_str(&format!("{:02x}", b)); }
    s
}

fn parse_rdata(data: &[u8], offset: usize, rdlen: usize, type_num: u16) -> (String, String, String, usize) {
    let end = offset + rdlen;
    if end > data.len() { return ("{\"bytes\":[]}".into(), "".into(), "".into(), end); }
    let slice = &data[offset..end];
    match type_num {
        1 => {
            if rdlen==4 {
                let ip = format!("{}.{}.{}.{}", slice[0], slice[1], slice[2], slice[3]);
                let json = format!("{{\"address\":\"{}\"}}", ip);
                (json, ip.clone(), ip, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        28 => {
            if rdlen==16 {
                let arr: [u8;16] = slice.try_into().unwrap_or([0;16]);
                let ip = std::net::Ipv6Addr::from(arr).to_string();
                let json = format!("{{\"address\":\"{}\"}}", ip);
                (json, ip.clone(), ip, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        5 => {
            let (name, _) = parse_name(data, offset);
            let json = format!("{{\"domain\":\"{}\"}}", name.replace('\"',"\\\""));
            let txt = format!("\"{}\"", name);
            (json, txt.clone(), txt, end)
        }
        2 => {
            let (name, _) = parse_name(data, offset);
            let json = format!("{{\"nameserver\":\"{}\"}}", name.replace('\"',"\\\""));
            let txt = format!("\"{}\"", name);
            (json, txt.clone(), txt, end)
        }
        12 => {
            let (name, _) = parse_name(data, offset);
            let json = format!("{{\"cname\":\"{}\"}}", name.replace('\"',"\\\""));
            let txt = format!("\"{}\"", name);
            (json, txt.clone(), txt, end)
        }
        15 => {
            if rdlen>=2 {
                let pref = u16::from_be_bytes([slice[0], slice[1]]);
                let (exchange, _) = parse_name(data, offset+2);
                let json = format!("{{\"preference\":{},\"exchange\":\"{}\"}}", pref, exchange.replace('\"',"\\\""));
                let txt = if exchange.is_empty() { format!("{} \"\"", pref) } else { format!("{} \"{}\"", pref, exchange) };
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        16 => {
            let mut msgs = Vec::new();
            let mut off = 0;
            while off < slice.len() {
                let l = slice[off] as usize;
                off+=1;
                if off+l > slice.len() { break; }
                let txt = String::from_utf8_lossy(&slice[off..off+l]).to_string();
                msgs.push(txt);
                off+=l;
            }
            let json_msgs = msgs.iter().map(|m| format!("\"{}\"", m.replace('\\',"\\\\").replace('\"',"\\\""))).collect::<Vec<_>>().join(",");
            let json = format!("{{\"messages\":[{}]}}", json_msgs);
            let txt = msgs.iter().map(|m| format!("\"{}\"", m)).collect::<Vec<_>>().join(" ");
            (json, txt.clone(), txt, end)
        }
        6 => {
            let (mname, off1) = parse_name(data, offset);
            let (rname, off2) = parse_name(data, off1);
            let mut cur = off2;
            let mut serial = 0u32;
            let mut refresh = 0u32;
            let mut retry = 0u32;
            let mut expire = 0u32;
            let mut minimum = 0u32;
            if cur + 20 <= data.len() {
                serial = u32::from_be_bytes([data[cur], data[cur+1], data[cur+2], data[cur+3]]);
                refresh = u32::from_be_bytes([data[cur+4], data[cur+5], data[cur+6], data[cur+7]]);
                retry = u32::from_be_bytes([data[cur+8], data[cur+9], data[cur+10], data[cur+11]]);
                expire = u32::from_be_bytes([data[cur+12], data[cur+13], data[cur+14], data[cur+15]]);
                minimum = u32::from_be_bytes([data[cur+16], data[cur+17], data[cur+18], data[cur+19]]);
            }
            let json = format!("{{\"mname\":\"{}\"}}", mname.replace('\"',"\\\""));
            let fmt = |v: u32| {
                let d = v / 86400;
                let h = (v % 86400) / 3600;
                let m = (v % 3600) / 60;
                let s = v % 60;
                if d>0 { format!("{}d{}h{:02}m{:02}s", d, h, m, s) }
                else if h>0 { format!("{}h{:02}m{:02}s", h, m, s) }
                else if m>0 { format!("{}m{:02}s", m, s) }
                else { format!("{}s", s) }
            };
            let txt = format!("\"{}\" \"{}\" {} {} {} {} {}", mname, rname, serial, fmt(refresh), fmt(retry), fmt(expire), fmt(minimum));
            (json, txt.clone(), txt, end)
        }
        33 => {
            if rdlen>=6 {
                let pri = u16::from_be_bytes([slice[0], slice[1]]);
                let wei = u16::from_be_bytes([slice[2], slice[3]]);
                let port = u16::from_be_bytes([slice[4], slice[5]]);
                let (target, _) = parse_name(data, offset+6);
                let json = format!("{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":\"{}\"}}", pri, wei, port, target.replace('\"',"\\\""));
                let txt = format!("{} {} \"{}\":{}", pri, wei, target, port);
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        35 => {
            if rdlen>=2 {
                let order = u16::from_be_bytes([slice[0], slice[1]]);
                let mut cur = 2;
                let mut pref = 0u16;
                if cur+2 <= slice.len() {
                    pref = u16::from_be_bytes([slice[cur], slice[cur+1]]);
                    cur+=2;
                }
                let mut flags = String::new();
                if cur < slice.len() {
                    let l = slice[cur] as usize; cur+=1;
                    if cur+l <= slice.len() { flags = String::from_utf8_lossy(&slice[cur..cur+l]).to_string(); cur+=l; }
                }
                let mut service = String::new();
                if cur < slice.len() {
                    let l = slice[cur] as usize; cur+=1;
                    if cur+l <= slice.len() { service = String::from_utf8_lossy(&slice[cur..cur+l]).to_string(); cur+=l; }
                }
                let mut regex = String::new();
                if cur < slice.len() {
                    let l = slice[cur] as usize; cur+=1;
                    if cur+l <= slice.len() { regex = String::from_utf8_lossy(&slice[cur..cur+l]).to_string(); cur+=l; }
                }
                let repl_off = offset + cur;
                let (replacement, _) = parse_name(data, repl_off);
                let json = format!("{{\"order\":{},\"flags\":\"{}\",\"service\":\"{}\",\"regex\":\"{}\",\"replacement\":\"{}\"}}", order, flags.replace('\"',"\\\""), service.replace('\"',"\\\""), regex.replace('\"',"\\\""), replacement.replace('\"',"\\\""));
                let txt = format!("{} {} \"{}\" \"{}\" \"{}\" \"{}\"", order, pref, flags, service, regex, replacement);
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        257 => {
            if rdlen>=2 {
                let critical = (slice[0] & 0x80) != 0;
                let tag_len = slice[1] as usize;
                if 2+tag_len <= slice.len() {
                    let tag = String::from_utf8_lossy(&slice[2..2+tag_len]).to_string();
                    let value = String::from_utf8_lossy(&slice[2+tag_len..]).to_string();
                    let json = format!("{{\"critical\":{},\"tag\":\"{}\",\"value\":\"{}\"}}", critical, tag.replace('\"',"\\\""), value.replace('\"',"\\\""));
                    let crit_str = if critical { "critical" } else { "non-critical" };
                    let txt = format!("\"{}\" \"{}\" ({})", tag, value, crit_str);
                    (json, txt.clone(), txt, end)
                } else {
                    let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                    (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
                }
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        13 => {
            if rdlen>=2 {
                let cpu_len = slice[0] as usize;
                let mut cpu = String::new();
                let mut os_str = String::new();
                if 1+cpu_len <= slice.len() {
                    cpu = String::from_utf8_lossy(&slice[1..1+cpu_len]).to_string();
                    let os_len_off = 1+cpu_len;
                    if os_len_off < slice.len() {
                        let os_len = slice[os_len_off] as usize;
                        if os_len_off+1+os_len <= slice.len() {
                            os_str = String::from_utf8_lossy(&slice[os_len_off+1..os_len_off+1+os_len]).to_string();
                        }
                    }
                }
                let json = format!("{{\"cpu\":\"{}\",\"os\":\"{}\"}}", cpu.replace('\"',"\\\""), os_str.replace('\"',"\\\""));
                let txt = format!("\"{}\" \"{}\"", cpu, os_str);
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        44 => {
            if rdlen>=2 {
                let algo = slice[0];
                let ftype = slice[1];
                let fp = hex_encode(&slice[2..]);
                let json = format!("{{\"algorithm\":{},\"fingerprint_type\":{},\"fingerprint\":\"{}\"}}", algo, ftype, fp);
                let txt = format!("{} {} {}", algo, ftype, fp);
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        52 => {
            if rdlen>=3 {
                let usage = slice[0];
                let sel = slice[1];
                let mt = slice[2];
                let cert = hex_encode(&slice[3..]);
                let json = format!("{{\"certificate_usage\":{},\"selector\":{},\"matching_type\":{},\"certificate_data\":\"{}\"}}", usage, sel, mt, cert);
                let txt = format!("{} {} {} \"{}\"", usage, sel, mt, cert);
                (json, txt.clone(), txt, end)
            } else {
                let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
                (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
            }
        }
        _ => {
            let b = slice.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",");
            (format!("{{\"bytes\":[{}]}}", b), format!("[{}]", b), format!("[{}]", b), end)
        }
    }
}

fn parse_response(data: &[u8], edns_mode: &str) -> Result<DnsResponse, String> {
    if data.len() < 12 { return Err("insufficient data".into()); }
    let flags = u16::from_be_bytes([data[2], data[3]]);
    let qdcount = u16::from_be_bytes([data[4], data[5]]);
    let ancount = u16::from_be_bytes([data[6], data[7]]);
    let nscount = u16::from_be_bytes([data[8], data[9]]);
    let arcount = u16::from_be_bytes([data[10], data[11]]);
    let rcode = flags & 0x000F;
    let has_nx = rcode == 3;

    let mut offset = 12usize;
    let mut queries_json_parts = Vec::new();
    for _ in 0..qdcount {
        let (qname, new_off) = parse_name(data, offset);
        offset = new_off;
        if offset+4 > data.len() { return Err("insufficient data".into()); }
        let qtype = u16::from_be_bytes([data[offset], data[offset+1]]);
        let qclass = u16::from_be_bytes([data[offset+2], data[offset+3]]);
        offset+=4;
        let tstr = num_to_type(qtype);
        let cstr = num_to_class(qclass);
        queries_json_parts.push(format!("{{\"name\":\"{}\",\"class\":\"{}\",\"type\":\"{}\"}}", qname.replace('\"',"\\\""), cstr, tstr));
    }
    let queries_json = format!("[{}]", queries_json_parts.join(","));

    let mut answers = Vec::new();
    let mut authorities = Vec::new();
    let mut additionals = Vec::new();

    for _ in 0..ancount {
        let (name, new_off) = parse_name(data, offset);
        offset = new_off;
        if offset+10 > data.len() { return Err("insufficient data".into()); }
        let typ = u16::from_be_bytes([data[offset], data[offset+1]]);
        let class = u16::from_be_bytes([data[offset+2], data[offset+3]]);
        let ttl = u32::from_be_bytes([data[offset+4], data[offset+5], data[offset+6], data[offset+7]]);
        let rdlen = u16::from_be_bytes([data[offset+8], data[offset+9]]) as usize;
        offset+=10;
        if offset+rdlen > data.len() { return Err("insufficient data".into()); }
        if typ==41 && edns_mode!="show" { offset+=rdlen; continue; }
        let (json_data, text_data, short_data, _) = if typ==41 {
            ( "{\"version\":0,\"data\":[]}".to_string(), format!("+ {} 0 0 0 []", class), format!("+ {} 0 0 0 []", class), offset+rdlen)
        } else {
            parse_rdata(data, offset, rdlen, typ)
        };
        offset+=rdlen;
        let tstr = if typ==41 { "OPT".to_string() } else { num_to_type(typ) };
        let cstr = if typ==41 { "IN".to_string() } else { num_to_class(class) };
        let name_final = if typ==41 { "".to_string() } else { name };
        answers.push(DnsAnswer{ name: name_final, class: cstr, ttl, type_str: tstr, data_json: json_data, text_data, short_data });
    }
    for _ in 0..nscount {
        let (name, new_off) = parse_name(data, offset);
        offset = new_off;
        if offset+10 > data.len() { return Err("insufficient data".into()); }
        let typ = u16::from_be_bytes([data[offset], data[offset+1]]);
        let class = u16::from_be_bytes([data[offset+2], data[offset+3]]);
        let ttl = u32::from_be_bytes([data[offset+4], data[offset+5], data[offset+6], data[offset+7]]);
        let rdlen = u16::from_be_bytes([data[offset+8], data[offset+9]]) as usize;
        offset+=10;
        if offset+rdlen > data.len() { return Err("insufficient data".into()); }
        if typ==41 && edns_mode!="show" { offset+=rdlen; continue; }
        let (json_data, text_data, short_data, _) = if typ==41 {
            ( "{\"version\":0,\"data\":[]}".to_string(), format!("+ {} 0 0 0 []", class), format!("+ {} 0 0 0 []", class), offset+rdlen)
        } else {
            parse_rdata(data, offset, rdlen, typ)
        };
        offset+=rdlen;
        let tstr = if typ==41 { "OPT".to_string() } else { num_to_type(typ) };
        let cstr = if typ==41 { "IN".to_string() } else { num_to_class(class) };
        authorities.push(DnsAnswer{ name, class: cstr, ttl, type_str: tstr, data_json: json_data, text_data, short_data });
    }
    for _ in 0..arcount {
        let (name, new_off) = parse_name(data, offset);
        offset = new_off;
        if offset+10 > data.len() { break; }
        let typ = u16::from_be_bytes([data[offset], data[offset+1]]);
        let class = u16::from_be_bytes([data[offset+2], data[offset+3]]);
        let ttl = u32::from_be_bytes([data[offset+4], data[offset+5], data[offset+6], data[offset+7]]);
        let rdlen = u16::from_be_bytes([data[offset+8], data[offset+9]]) as usize;
        offset+=10;
        if offset+rdlen > data.len() { break; }
        if typ==41 && edns_mode!="show" { offset+=rdlen; continue; }
        if typ==41 {
            let json = "{\"version\":0,\"data\":[]}".to_string();
            additionals.push(DnsAnswer{ name: "".to_string(), class: "".to_string(), ttl: class as u32, type_str: "OPT".to_string(), data_json: json, text_data: format!("+ {} 0 0 0 []", class), short_data: "".into() });
        } else {
            let (json_data, text_data, short_data, _) = parse_rdata(data, offset, rdlen, typ);
            let tstr = num_to_type(typ);
            let cstr = num_to_class(class);
            let ttl_real = u32::from_be_bytes([data[offset-6], data[offset-5], data[offset-4], data[offset-3]]);
            additionals.push(DnsAnswer{ name, class: cstr, ttl: ttl_real, type_str: tstr, data_json: json_data, text_data, short_data });
        }
        offset+=rdlen;
    }

    Ok(DnsResponse{ queries_json, answers, authorities, additionals, has_nx })
}

fn main() {
    let raw_args: Vec<String> = std::env::args().skip(1).collect();

    #[derive(Clone, PartialEq)]
    enum ColorMode { Always, Automatic, Never }

    #[derive(Default)]
    struct Seen {
        query: Vec<String>,
        qtype: Vec<String>,
        nameserver: Vec<String>,
        class: Vec<String>,
        edns: Option<String>,
        txid: Option<String>,
        tweaks: Vec<String>,
        udp: bool, tcp: bool, tls: bool, https: bool,
        short: bool, json: bool,
        color: Option<String>,
        colour: Option<String>,
        seconds: bool, time: bool,
        help: bool, version: bool,
    }

    let mut seen = Seen::default();
    let mut bare_args: Vec<String> = Vec::new();
    let mut error: Option<String> = None;
    let mut i = 0;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "--" {
            i+=1;
            while i < raw_args.len() { bare_args.push(raw_args[i].clone()); i+=1; }
            break;
        } else if arg.starts_with("--") {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos+1..];
                match name {
                    "--query" => seen.query.push(value.to_string()),
                    "--type" => seen.qtype.push(value.to_string()),
                    "--nameserver" => seen.nameserver.push(value.to_string()),
                    "--class" => seen.class.push(value.to_string()),
                    "--edns" => {
                        if seen.edns.is_some() { error = Some("Option 'edns' given more than once".into()); break; }
                        seen.edns = Some(value.to_string());
                    }
                    "--txid" => {
                        if seen.txid.is_some() { error = Some("Option 'txid' given more than once".into()); break; }
                        seen.txid = Some(value.to_string());
                    }
                    "--color" => {
                        if seen.color.is_some() { error = Some("Option 'color' given more than once".into()); break; }
                        seen.color = Some(value.to_string());
                    }
                    "--colour" => {
                        if seen.colour.is_some() { error = Some("Option 'colour' given more than once".into()); break; }
                        seen.colour = Some(value.to_string());
                    }
                    _ => {
                        let opt = &name[2..];
                        error = Some(format!("Unrecognized option: '{}'", opt));
                        break;
                    }
                }
                i+=1;
            } else {
                match arg.as_str() {
                    "--query" => { if i+1>=raw_args.len() { error = Some("Argument to option 'query' missing".into()); break; } seen.query.push(raw_args[i+1].clone()); i+=2; }
                    "--type" => { if i+1>=raw_args.len() { error = Some("Argument to option 'type' missing".into()); break; } seen.qtype.push(raw_args[i+1].clone()); i+=2; }
                    "--nameserver" => { if i+1>=raw_args.len() { error = Some("Argument to option 'nameserver' missing".into()); break; } seen.nameserver.push(raw_args[i+1].clone()); i+=2; }
                    "--class" => { if i+1>=raw_args.len() { error = Some("Argument to option 'class' missing".into()); break; } seen.class.push(raw_args[i+1].clone()); i+=2; }
                    "--edns" => {
                        if seen.edns.is_some() { error = Some("Option 'edns' given more than once".into()); break; }
                        if i+1>=raw_args.len() { error = Some("Argument to option 'edns' missing".into()); break; }
                        seen.edns = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--txid" => {
                        if seen.txid.is_some() { error = Some("Option 'txid' given more than once".into()); break; }
                        if i+1>=raw_args.len() { error = Some("Argument to option 'txid' missing".into()); break; }
                        seen.txid = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--color" => {
                        if seen.color.is_some() { error = Some("Option 'color' given more than once".into()); break; }
                        if i+1>=raw_args.len() { error = Some("Argument to option 'color' missing".into()); break; }
                        seen.color = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--colour" => {
                        if seen.colour.is_some() { error = Some("Option 'colour' given more than once".into()); break; }
                        if i+1>=raw_args.len() { error = Some("Argument to option 'colour' missing".into()); break; }
                        seen.colour = Some(raw_args[i+1].clone()); i+=2;
                    }
                    "--udp" => { if seen.udp { error = Some("Option 'udp' given more than once".into()); break; } seen.udp=true; i+=1; }
                    "--tcp" => { if seen.tcp { error = Some("Option 'tcp' given more than once".into()); break; } seen.tcp=true; i+=1; }
                    "--tls" => { if seen.tls { error = Some("Option 'tls' given more than once".into()); break; } seen.tls=true; i+=1; }
                    "--https" => { if seen.https { error = Some("Option 'https' given more than once".into()); break; } seen.https=true; i+=1; }
                    "--short" => { if seen.short { error = Some("Option 'short' given more than once".into()); break; } seen.short=true; i+=1; }
                    "--json" => { if seen.json { error = Some("Option 'json' given more than once".into()); break; } seen.json=true; i+=1; }
                    "--seconds" => { if seen.seconds { error = Some("Option 'seconds' given more than once".into()); break; } seen.seconds=true; i+=1; }
                    "--time" => { if seen.time { error = Some("Option 'time' given more than once".into()); break; } seen.time=true; i+=1; }
                    "--help" => { if seen.help { error = Some("Option 'help' given more than once".into()); break; } seen.help=true; i+=1; }
                    "--version" => { if seen.version { error = Some("Option 'version' given more than once".into()); break; } seen.version=true; i+=1; }
                    _ => { let opt=&arg[2..]; error=Some(format!("Unrecognized option: '{}'", opt)); break; }
                }
            }
        } else if arg.starts_with("-") && arg.len()>1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j=0;
            let mut consumed_next=false;
            while j<chars.len() {
                let c=chars[j];
                match c {
                    'q' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() { seen.query.push(rest); break; }
                        else { if i+1>=raw_args.len() { error=Some("Argument to option 'q' missing".into()); break; } seen.query.push(raw_args[i+1].clone()); consumed_next=true; break; }
                    }
                    't' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() { seen.qtype.push(rest); break; }
                        else { if i+1>=raw_args.len() { error=Some("Argument to option 't' missing".into()); break; } seen.qtype.push(raw_args[i+1].clone()); consumed_next=true; break; }
                    }
                    'n' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() { seen.nameserver.push(rest); break; }
                        else { if i+1>=raw_args.len() { error=Some("Argument to option 'n' missing".into()); break; } seen.nameserver.push(raw_args[i+1].clone()); consumed_next=true; break; }
                    }
                    'Z' => {
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() { seen.tweaks.push(rest); break; }
                        else { if i+1>=raw_args.len() { error=Some("Argument to option 'Z' missing".into()); break; } seen.tweaks.push(raw_args[i+1].clone()); consumed_next=true; break; }
                    }
                    'U' => { if seen.udp { error=Some("Option 'udp' given more than once".into()); break; } seen.udp=true; j+=1; continue; }
                    'T' => { if seen.tcp { error=Some("Option 'tcp' given more than once".into()); break; } seen.tcp=true; j+=1; continue; }
                    'S' => { if seen.tls { error=Some("Option 'tls' given more than once".into()); break; } seen.tls=true; j+=1; continue; }
                    'H' => { if seen.https { error=Some("Option 'https' given more than once".into()); break; } seen.https=true; j+=1; continue; }
                    '1' => { if seen.short { error=Some("Option 'short' given more than once".into()); break; } seen.short=true; j+=1; continue; }
                    'J' => { if seen.json { error=Some("Option 'json' given more than once".into()); break; } seen.json=true; j+=1; continue; }
                    '?' => { if seen.help { error=Some("Option 'help' given more than once".into()); break; } seen.help=true; j+=1; continue; }
                    'v' => { if seen.version { error=Some("Option 'version' given more than once".into()); break; } seen.version=true; j+=1; continue; }
                    _ => { error=Some(format!("Unrecognized option: '{}'", c)); break; }
                }
            }
            if error.is_some() { break; }
            i+=1;
            if consumed_next { i+=1; }
        } else {
            bare_args.push(arg.clone());
            i+=1;
        }
    }

    if let Some(err) = error {
        eprintln!("dog: Invalid options: {}", err);
        std::process::exit(3);
    }

    let mut final_mode = ColorMode::Automatic;
    if let Some(v) = seen.color.as_ref() {
        match v.as_str() { "always" => final_mode=ColorMode::Always, "never" => final_mode=ColorMode::Never, "automatic" => final_mode=ColorMode::Automatic, _ => final_mode=ColorMode::Automatic, }
    } else if let Some(v) = seen.colour.as_ref() {
        match v.as_str() { "always" => final_mode=ColorMode::Always, "never" => final_mode=ColorMode::Never, "automatic" => final_mode=ColorMode::Automatic, _ => final_mode=ColorMode::Automatic, }
    }

    let use_color = match final_mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Automatic => std::io::stdout().is_terminal(),
    };

    if seen.version {
        if use_color { print!("{}", VERSION_ALWAYS); } else { print!("{}", VERSION_NEVER); }
        std::process::exit(0);
    }
    if seen.help {
        if use_color { print!("{}", HELP_ALWAYS); } else { print!("{}", HELP_NEVER); }
        std::process::exit(0);
    }

    let valid_types = ["A","AAAA","AFSDB","ANY","APL","AXFR","CAA","CDNSKEY","CDS","CERT","CNAME","CSYNC","DHCID","DLV","DNAME","DS","HINFO","HIP","IPSECKEY","IXFR","KEY","KX","LOC","MX","NAPTR","NS","NSEC","NSEC3","NSEC3PARAM","OPENPGPKEY","OPT","PTR","RP","RRSIG","SIG","SMIMEA","SOA","SRV","SSHFP","TA","TKEY","TLSA","TSIG","TXT","URI","EUI48","EUI64"];

    let mut domains: Vec<String> = Vec::new();
    let mut types: Vec<String> = Vec::new();
    let mut classes: Vec<String> = Vec::new();
    let mut nameservers: Vec<String> = Vec::new();

    for q in &seen.query { domains.push(q.clone()); }
    for t in &seen.qtype {
        if t.is_empty() { eprintln!("dog: Invalid options: Invalid query type \"{}\"", t); std::process::exit(3); }
        let up = t.to_uppercase();
        if !valid_types.contains(&up.as_str()) { eprintln!("dog: Invalid options: Invalid query type \"{}\"", t); std::process::exit(3); }
        types.push(up);
    }
    for n in &seen.nameserver { nameservers.push(n.clone()); }
    for c in &seen.class {
        if c.is_empty() { eprintln!("dog: Invalid options: Invalid query class \"{}\"", c); std::process::exit(3); }
        let up = c.to_uppercase();
        if !["IN","CH","HS"].contains(&up.as_str()) { eprintln!("dog: Invalid options: Invalid query class \"{}\"", c); std::process::exit(3); }
        classes.push(up);
    }

    for bare in &bare_args {
        if bare.starts_with('@') { nameservers.push(bare[1..].to_string()); }
        else {
            let up = bare.to_uppercase();
            if valid_types.contains(&up.as_str()) { types.push(up); }
            else if ["IN","CH","HS"].contains(&up.as_str()) { classes.push(up); }
            else {
                if bare.starts_with('-') { eprintln!("dog: Invalid options: Invalid domain \"{}\"", bare); std::process::exit(3); }
                domains.push(bare.clone());
            }
        }
    }

    if domains.is_empty() {
        if use_color { print!("{}", HELP_ALWAYS); } else { print!("{}", HELP_NEVER); }
        std::process::exit(3);
    }

    if types.is_empty() { types.push("A".into()); }
    if classes.is_empty() { classes.push("IN".into()); }

    let edns_mode_str = match seen.edns.as_deref() {
        Some("disable") => "disable",
        Some("hide") => "hide",
        Some("show") => "show",
        Some(v) => { eprintln!("dog: Invalid options: Invalid EDNS setting \"{}\"", v); std::process::exit(3); }
        None => "hide",
    };

    let txid_val: Option<u16> = match seen.txid.as_deref() {
        Some(s) => match s.parse::<u32>() { Ok(n) if n<=65535 => Some(n as u16), _ => { eprintln!("dog: Invalid options: Invalid transaction ID \"{}\"", s); std::process::exit(3); } },
        None => None,
    };

    let mut tweak_aa=false; let mut tweak_ad=false; let mut tweak_cd=false; let mut tweak_bufsize: Option<u16>=None;
    for tw in &seen.tweaks {
        if tw.is_empty() { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
        match tw.as_str() {
            "aa" => tweak_aa=true,
            "ad" => tweak_ad=true,
            "cd" => tweak_cd=true,
            _ if tw.starts_with("bufsize=") => {
                let v=&tw["bufsize=".len()..];
                if v.is_empty() { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
                match v.parse::<u32>() { Ok(n) if n<=65535 => tweak_bufsize=Some(n as u16), _ => { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); } }
            }
            _ => { eprintln!("dog: Invalid options: Invalid protocol tweak \"{}\"", tw); std::process::exit(3); }
        }
    }

    let mut transports: Vec<&str> = Vec::new();
    if seen.udp { transports.push("udp"); }
    if seen.tcp { transports.push("tcp"); }
    if seen.tls { transports.push("tls"); }
    if seen.https { transports.push("https"); }
    if transports.is_empty() { transports.push("auto"); }

    if transports.contains(&"https") {
        let has_url = nameservers.iter().any(|ns| ns.starts_with("https://") || ns.starts_with("http://"));
        if !has_url { eprintln!("dog: Invalid options: You must pass a URL as a nameserver when using --https"); std::process::exit(3); }
    }

    let start_all = Instant::now();
    let hosts_map = load_hosts();
    let mut warned = HashSet::new();
    let default_ns: Vec<String> = {
        let mut ns=Vec::new();
        if let Ok(content)=std::fs::read_to_string("/etc/resolv.conf") {
            for line in content.lines() {
                let l=line.trim();
                if l.starts_with("nameserver") {
                    let p: Vec<&str>=l.split_whitespace().collect();
                    if p.len()>=2 { ns.push(p[1].to_string()); }
                }
            }
        }
        if ns.is_empty() { ns.push("10.0.0.2".into()); }
        ns
    };
    let effective_ns = if nameservers.is_empty() { default_ns } else { nameservers.clone() };

    let mut all_responses: Vec<DnsResponse> = Vec::new();
    let mut net_err: Option<String>=None;
    let mut proto_err: Option<String>=None;

    for domain in &domains {
        let fqdn = if domain.ends_with('.') { domain.clone() } else { format!("{}.", domain) };
        let key = domain.trim_end_matches('.').to_lowercase();
        if hosts_map.contains_key(&key) && !warned.contains(&key) {
            eprintln!("warning: domain '{}' also exists in hosts file", fqdn.to_lowercase());
            warned.insert(key.clone());
        }
        for qtype in &types {
            for qclass in &classes {
                for ns_str in &effective_ns {
                    for transport in &transports {
                        let txid = if let Some(v)=txid_val { v } else {
                            let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.subsec_nanos()).unwrap_or(0);
                            (nanos % 65536) as u16
                        };
                        let qtype_num = type_to_num(qtype);
                        let qclass_num = class_to_num(qclass);
                        let packet = build_query(txid, domain, qtype_num, qclass_num, edns_mode_str, tweak_bufsize, tweak_aa, tweak_ad, tweak_cd);
                        let sock_addr = match resolve_ns(ns_str) {
                            Ok(sa) => sa,
                            Err(e) => { net_err=Some(e); continue; }
                        };
                        let resp_res = match *transport {
                            "udp" => query_udp(&packet, sock_addr),
                            "tcp" => query_tcp(&packet, sock_addr),
                            "auto" => {
                                match query_udp(&packet, sock_addr) {
                                    Ok(b) => {
                                        if b.len()>=3 && (b[2] & 0x02)!=0 {
                                            match query_tcp(&packet, sock_addr) {
                                                Ok(b2) => Ok(b2),
                                                Err(e) => Err(e),
                                            }
                                        } else { Ok(b) }
                                    }
                                    Err(e) => Err(e),
                                }
                            }
                            "tls" => {
                                let mut sa = sock_addr;
                                if sa.port()==53 { sa.set_port(853); }
                                match query_tcp(&packet, sa) {
                                    Ok(b) => Ok(b),
                                    Err(e) => Err(e),
                                }
                            }
                            "https" => Err("Operation not permitted (os error 1)".to_string()),
                            _ => query_udp(&packet, sock_addr),
                        };
                        let resp_bytes = match resp_res {
                            Ok(b) => b,
                            Err(e) => { net_err=Some(e); continue; }
                        };
                        match parse_response(&resp_bytes, edns_mode_str) {
                            Ok(dr) => all_responses.push(dr),
                            Err(e) => { proto_err=Some(format!("Malformed packet: {}", e)); }
                        }
                    }
                }
            }
        }
    }

    let duration = start_all.elapsed();
    let secs = duration.as_secs();
    let millis = duration.subsec_millis() as u64;

    if net_err.is_some() || proto_err.is_some() {
        let (phase, msg) = if let Some(p)=proto_err { ("protocol", p) } else { ("network", net_err.clone().unwrap()) };
        if seen.json && !seen.short {
            if seen.time {
                println!("{{\"responses\":[],\"duration\":{{\"secs\":{},\"millis\":{}}}}}", secs, millis);
            } else {
                println!("{{\"responses\":[]}}");
            }
            eprintln!("{{\"error\":true,\"error_phase\":\"{}\",\"error_message\":\"{}\"}}", phase, msg.replace('\"',"\\\""));
            std::process::exit(1);
        } else {
            eprintln!("Error [{}]: {}", phase, msg);
            if seen.time && !seen.json {
                println!("Ran in {}ms", if secs==0 && millis==0 {0} else { secs*1000 + millis });
            }
            if seen.short {
                eprintln!("No results");
                std::process::exit(2);
            }
            std::process::exit(1);
        }
    }

    if seen.json && !seen.short {
        let mut resp_strs = Vec::new();
        for r in &all_responses {
            let ans_str = r.answers.iter().map(|a| {
                format!("{{\"name\":\"{}\",\"class\":\"{}\",\"ttl\":{},\"type\":\"{}\",\"data\":{}}}", a.name.replace('\"',"\\\""), a.class, a.ttl, a.type_str, a.data_json)
            }).collect::<Vec<_>>().join(",");
            let auth_str = r.authorities.iter().map(|a| {
                format!("{{\"name\":\"{}\",\"class\":\"{}\",\"ttl\":{},\"type\":\"{}\",\"data\":{}}}", a.name.replace('\"',"\\\""), a.class, a.ttl, a.type_str, a.data_json)
            }).collect::<Vec<_>>().join(",");
            let add_str = r.additionals.iter().map(|a| {
                if a.type_str=="OPT" {
                    format!("{{\"name\":\"{}\",\"type\":\"{}\",\"data\":{}}}", a.name.replace('\"',"\\\""), a.type_str, a.data_json)
                } else {
                    format!("{{\"name\":\"{}\",\"class\":\"{}\",\"ttl\":{},\"type\":\"{}\",\"data\":{}}}", a.name.replace('\"',"\\\""), a.class, a.ttl, a.type_str, a.data_json)
                }
            }).collect::<Vec<_>>().join(",");
            let resp_json = format!("{{\"queries\":{},\"answers\":[{}],\"authorities\":[{}],\"additionals\":[{}]}}", r.queries_json, ans_str, auth_str, add_str);
            resp_strs.push(resp_json);
        }
        let joined = resp_strs.join(",");
        if seen.time {
            println!("{{\"responses\":[{}],\"duration\":{{\"secs\":{},\"millis\":{}}}}}", joined, secs, millis);
        } else {
            println!("{{\"responses\":[{}]}}", joined);
        }
        std::process::exit(0);
    }

    if seen.short {
        let mut any=false;
        for r in &all_responses {
            for a in &r.answers {
                println!("{}", a.short_data);
                any=true;
            }
        }
        if !any {
            eprintln!("No results");
            std::process::exit(2);
        }
        if seen.time {
            println!("Ran in {}ms", if secs==0 && millis==0 {0} else { secs*1000 + millis });
        }
        std::process::exit(0);
    }

    for r in &all_responses {
        if r.has_nx { println!("Status: NXDomain"); }
        let has_auth = !r.authorities.is_empty();
        for ans in &r.answers {
            let indent = if has_auth { "  " } else { "" };
            let ttl_str = fmt_ttl(ans.ttl, seen.seconds);
            let type_c = if use_color {
                match ans.type_str.as_str() {
                    "A" | "AAAA" => format!("\x1b[1;32m{}\x1b[0m", ans.type_str),
                    "MX" | "SRV" | "SSHFP" => format!("\x1b[36m{}\x1b[0m", ans.type_str),
                    "NS" | "PTR" | "NAPTR" | "CAA" => format!("\x1b[31m{}\x1b[0m", ans.type_str),
                    "SOA" => format!("\x1b[35m{}\x1b[0m", ans.type_str),
                    "TXT" | "CNAME" | "HINFO" | "LOC" | "TLSA" => format!("\x1b[33m{}\x1b[0m", ans.type_str),
                    _ => ans.type_str.clone(),
                }
            } else { ans.type_str.clone() };
