                        _ => add.type_str.clone(),
                    }
                } else { add.type_str.clone() };
                let name_c = if use_color { format!("\x1b[1;34m{}\x1b[0m", add.name) } else { add.name.clone() };
                let sec_c = if use_color { "\x1b[32m+\x1b[0m".to_string() } else { "+".to_string() };
                println!("{}{} {} {} {} {}", indent, type_c, name_c, ttl_str, sec_c, add.text_data);
            }
        }
    }
    if seen.time {
        let total = if secs==0 && millis==0 {0} else { secs*1000 + millis };
        println!("Ran in {}ms", total);
    }
}
