import socket, threading, struct, time, subprocess, os

def enc(name):
    return b''.join(struct.pack('B', len(p.encode()))+p.encode() for p in name.rstrip('.').split('.'))+b'\x00'

def build(data, answers, authorities, additionals, rcode=0):
    txid = data[0:2]
    flags = struct.pack('!H', 0x8180 | rcode)
    qdcount = struct.unpack('!H', data[4:6])[0]
    header = txid + flags + struct.pack('!HHHH', qdcount, len(answers), len(authorities), len(additionals))
    pos=12
    while pos < len(data):
        l=data[pos]
        if l==0:
            pos+=1
            break
        pos+=1+l
    question = data[12:pos+4]
    out=header+question
    for typ, rdata, ttl in answers:
        out+=struct.pack('!H',0xC00C)+struct.pack('!HHIH',typ,1,ttl,len(rdata))+rdata
    for typ, rdata, ttl in authorities:
        out+=struct.pack('!H',0xC00C)+struct.pack('!HHIH',typ,1,ttl,len(rdata))+rdata
    for typ, rdata, ttl in additionals:
        if typ==41:
            out+=b'\x00'+struct.pack('!HHIH',41,4096,0,len(rdata))+rdata
        else:
            out+=struct.pack('!H',0xC00C)+struct.pack('!HHIH',typ,1,ttl,len(rdata))+rdata
    return out

def a(ip): return socket.inet_aton(ip)
def soa():
    return enc('ns1.example.com.')+enc('host.example.com.')+struct.pack('!IIIII',2020010101,3600,600,86400,300)

