            elif scen=="onlyauth":
                ans=[]; auth=[(6,soa(),300)]; add=[]
            elif scen=="onlyadd":
                ans=[]; auth=[]; add=[(1,a('5.6.7.8'),300)]
            elif scen=="onlyopt":
                ans=[]; auth=[]; add=[(41,b'',300)]
            elif scen=="aauth":
                ans=[(1,a('1.2.3.4'),300)]; auth=[(6,soa(),300)]; add=[]
            elif scen=="aadd":
                ans=[(1,a('1.2.3.4'),300)]; auth=[]; add=[(1,a('5.6.7.8'),300)]
            elif scen=="aadd2":
                ans=[(1,a('1.2.3.4'),300),(1,a('1.2.3.5'),300)]; auth=[]; add=[(1,a('5.6.7.8'),300)]
            elif scen=="aauthadd":
                ans=[(1,a('1.2.3.4'),300)]; auth=[(6,soa(),300)]; add=[(1,a('5.6.7.8'),300)]
            elif scen=="authadd":
                ans=[]; auth=[(6,soa(),300)]; add=[(1,a('5.6.7.8'),300)]
            elif scen=="aopt":
